/**
 * GhostQuest / QuestKit — Discord desktop inject (main process)
 *
 * Versão local e limpa:
 *   - sem proxy de token
 *   - sem envio de credenciais para servidor
 *   - sem update remoto
 *
 * O único serviço local é um relay loopback (127.0.0.1, porta aleatória,
 * chave aleatória por execução) usado para falar com
 * https://<app_id>.discordsays.com/.proxy/acf/*, que o CSP do renderer
 * bloqueia. O relay NÃO aceita header Authorization e só encaminha POSTs
 * para authorize / quest/progress do mesmo app informado na URL.
 */
'use strict';

if (global.__ghostquestMain) {
  module.exports = {};
} else {
  global.__ghostquestMain = true;

  const fs = require('fs');
  const path = require('path');
  const http = require('http');
  const https = require('https');
  const crypto = require('crypto');

  const rendererPath = path.join(__dirname, 'renderer.js');

  let RENDERER = '';
  try {
    RENDERER = fs.readFileSync(rendererPath, 'utf8');
  } catch (e) {
    console.error('[GhostQuest] renderer.js ausente:', e && e.message ? e.message : e);
  }

  // Ícone e fonte embutidos em base64: o pacote do plugin fica com 3 arquivos.
  const ICON_B64 = '';
  const FONT_B64 = '';

  const ICON = ICON_B64 ? 'data:image/png;base64,' + ICON_B64 : '';

  let FONT = null;
  try {
    FONT = FONT_B64 ? Buffer.from(FONT_B64, 'base64') : null;
  } catch (e) {
    console.error('[GhostQuest] falha ao decodificar a fonte embutida:', e && e.message ? e.message : e);
  }

  // ------------------------------------------------------------ relay local

  const USER_AGENT =
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 ' +
    '(KHTML, like Gecko) discord/1.0.9262 Chrome/139.0.7204.251 Electron/38.0.0 Safari/537.36';

  const TARGET_RE = /^https:\/\/(\d{5,25})\.discordsays\.com\/\.proxy\/acf\/(authorize|quest\/progress)$/;
  const ALLOWED_HEADERS = new Set(['x-auth-token', 'x-discord-quest-id', 'referer']);
  const MAX_BODY = 16 * 1024;

  let relay = null;

  function postJson(target, headers, payload, timeoutMs) {
    return new Promise((resolve, reject) => {
      const url = new URL(target);
      const data = JSON.stringify(payload);
      const finalHeaders = Object.assign(
        {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(data),
          'User-Agent': USER_AGENT,
        },
        headers
      );

      const req = https.request(
        {
          hostname: url.hostname,
          path: url.pathname + url.search,
          method: 'POST',
          headers: finalHeaders,
          timeout: timeoutMs || 15000,
        },
        (res) => {
          let raw = '';
          res.setEncoding('utf8');
          res.on('data', (chunk) => {
            if (raw.length < 131072) raw += chunk;
          });
          res.on('end', () => {
            let body = raw;
            try {
              body = JSON.parse(raw);
            } catch (_) {}
            resolve({
              ok: res.statusCode >= 200 && res.statusCode < 300,
              status: res.statusCode,
              body,
            });
          });
        }
      );

      req.on('timeout', () => req.destroy(new Error('timeout')));
      req.on('error', reject);
      req.write(data);
      req.end();
    });
  }

  function readBody(req) {
    return new Promise((resolve, reject) => {
      let raw = '';
      req.setEncoding('utf8');
      req.on('data', (chunk) => {
        raw += chunk;
        if (raw.length > MAX_BODY) {
          reject(new Error('corpo grande demais'));
          req.destroy();
        }
      });
      req.on('end', () => resolve(raw));
      req.on('error', reject);
    });
  }

  function cors(res, req) {
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'content-type');
    res.setHeader('Access-Control-Max-Age', '600');
    if (req.headers['access-control-request-private-network'] === 'true') {
      res.setHeader('Access-Control-Allow-Private-Network', 'true');
    }
  }

  function send(res, status, payload) {
    if (res.writableEnded) return;
    res.statusCode = status;
    res.setHeader('Content-Type', 'application/json');
    res.end(JSON.stringify(payload));
  }

  async function handleRelay(req, res, key) {
    cors(res, req);

    if (req.method === 'OPTIONS') {
      res.statusCode = 204;
      res.end();
      return;
    }

    if (req.method === 'GET' && req.url === '/gq-' + key + '/font') {
      if (!FONT || !FONT.length) {
        send(res, 404, { ok: false, error: 'fonte ausente' });
        return;
      }
      res.statusCode = 200;
      res.setHeader('Content-Type', 'font/woff2');
      res.setHeader('Cache-Control', 'no-store');
      res.end(FONT);
      return;
    }

    if (req.method !== 'POST' || req.url !== '/gq-' + key + '/proxy') {
      send(res, 404, { ok: false, error: 'not found' });
      return;
    }

    let parsed;
    try {
      parsed = JSON.parse(await readBody(req));
    } catch (e) {
      send(res, 400, { ok: false, error: 'json inválido' });
      return;
    }

    const target = parsed && parsed.url;
    const match = typeof target === 'string' ? TARGET_RE.exec(target) : null;
    if (!match) {
      send(res, 400, { ok: false, error: 'destino não permitido' });
      return;
    }

    const appId = match[1];
    const headers = {};

    if (parsed.headers && typeof parsed.headers === 'object') {
      for (const [name, value] of Object.entries(parsed.headers)) {
        if (!ALLOWED_HEADERS.has(String(name).toLowerCase())) continue;
        if (typeof value !== 'string' || value.length > 4096) continue;
        headers[name] = value;
      }
    }

    if (headers.Referer) {
      try {
        const ref = new URL(headers.Referer);
        if (ref.protocol !== 'https:' || ref.hostname !== appId + '.discordsays.com') {
          send(res, 400, { ok: false, error: 'referer inválido' });
          return;
        }
      } catch (_) {
        send(res, 400, { ok: false, error: 'referer inválido' });
        return;
      }
    }

    try {
      const result = await postJson(target, headers, parsed.body || {});
      send(res, 200, result);
    } catch (error) {
      send(res, 502, {
        ok: false,
        status: 0,
        error: String(error && error.message ? error.message : error),
      });
    }
  }

  function startRelay() {
    if (relay) return relay;

    const key = crypto.randomBytes(24).toString('hex');
    const state = { key, url: null, server: null };

    const server = http.createServer((req, res) => {
      handleRelay(req, res, key).catch((error) => {
        send(res, 500, { ok: false, error: String(error && error.message ? error.message : error) });
      });
    });

    server.on('error', (error) => {
      state.url = null;
      console.error('[GhostQuest] relay local falhou:', error && error.message ? error.message : error);
    });

    server.listen(0, '127.0.0.1', () => {
      try {
        const port = server.address().port;
        state.url = 'http://127.0.0.1:' + port;
        console.log('[GhostQuest] relay local em ' + state.url);
      } catch (_) {}
    });

    state.server = server;
    relay = state;

    try {
      const { app } = require('electron');
      app.on('will-quit', () => {
        try { server.close(); } catch (_) {}
      });
    } catch (_) {}

    return state;
  }

  // ------------------------------------------------------------ injection

  function alive(win) {
    try {
      return !!(win && !win.isDestroyed() && win.webContents && !win.webContents.isDestroyed());
    } catch (_) {
      return false;
    }
  }

  function isSplash(win) {
    try {
      const title = String(win.getTitle() || '').toLowerCase();
      const url = win.webContents.getURL() || '';
      if (!url || url === 'about:blank') return true;
      if (url.includes('splash') || url.includes('updating')) return true;
      if (title === 'discord' && !url.includes('discord.com')) return true;
      return false;
    } catch (_) {
      return true;
    }
  }

  function relayReady() {
    return !!(relay && relay.url);
  }

  function bootstrap() {
    return (
      'window.__GHOSTQUEST_RELAY__=' +
      JSON.stringify({ url: relay.url, key: relay.key }) +
      ';\n' +
      'window.__GHOSTQUEST_ICON__=' +
      JSON.stringify(ICON) +
      ';\n'
    );
  }

  function runInject(win) {
    if (!RENDERER || !alive(win) || isSplash(win)) return;
    if (!relayReady()) {
      setTimeout(() => runInject(win), 800);
      return;
    }
    try {
      win.webContents.executeJavaScript(bootstrap() + RENDERER).catch(() => {});
    } catch (_) {}
  }

  function inject(win) {
    if (!alive(win) || !RENDERER) return;

    const timers = [];
    const schedule = (ms) => {
      const id = setTimeout(() => {
        if (alive(win)) runInject(win);
      }, ms);
      timers.push(id);
    };

    const onReady = () => {
      schedule(1500);
      schedule(4000);
      schedule(9000);
    };

    try {
      win.webContents.on('dom-ready', () => {
        if (!alive(win) || isSplash(win)) return;
        schedule(800);
        schedule(2500);
      });

      win.webContents.on('did-finish-load', () => {
        if (!alive(win) || isSplash(win)) return;
        schedule(500);
        schedule(3000);
      });

      win.on('closed', () => timers.forEach((t) => clearTimeout(t)));

      if (!isSplash(win)) onReady();
    } catch (_) {}
  }

  try {
    const { app, BrowserWindow } = require('electron');

    startRelay();

    const boot = () => {
      try {
        BrowserWindow.getAllWindows().forEach(inject);
      } catch (_) {}

      app.on('browser-window-created', (_e, win) => {
        setTimeout(() => {
          try { inject(win); } catch (_) {}
        }, 500);
      });

      console.log('[GhostQuest] main hook ativo (modo local, sem servidor externo)');
    };

    if (app.isReady()) boot();
    else app.whenReady().then(boot);
  } catch (e) {
    console.error('[GhostQuest] falha no main hook', e);
  }

  module.exports = {};
}
